{
  "name": "BRUTAL STATUS // GEN",
  "description": "A brutalist aesthetic WhatsApp status generator powered by Gemini AI. Generate punchy text and export high-res 9:16 PNGs."
}

export type Tone = 'Sarcástico' | 'Motivacional' | 'Minimalista' | 'Romântico' | 'Caótico' | 'Sad';

export type FontStyle = 'font-sans' | 'font-mono' | 'font-display';

export type Alignment = 'text-left' | 'text-center' | 'text-right';

export interface Palette {
  name: string;
  bg: string;
  text: string;
  border: string;
}

export interface CardConfig {
  text: string;
  font: FontStyle;
  fontSize: number; // in pixels (base for calculation)
  alignment: Alignment;
  padding: number;
  palette: Palette;
  hasNoise: boolean;
  uppercase: boolean;
}

export interface GeneratedOption {
  id: string;
  text: string;
}

import { Palette, Tone } from './types';

export const TONES: Tone[] = ['Motivacional', 'Sarcástico', 'Minimalista', 'Romântico', 'Caótico', 'Sad'];

export const PALETTES: Palette[] = [
  { name: 'P&B', bg: '#ffffff', text: '#000000', border: '#000000' },
  { name: 'DARK', bg: '#000000', text: '#ffffff', border: '#ffffff' },
  { name: 'ACID', bg: '#ccff00', text: '#000000', border: '#000000' },
  { name: 'BLUE', bg: '#0000ff', text: '#ffffff', border: '#000000' },
  { name: 'WARNING', bg: '#ffff00', text: '#000000', border: '#000000' },
  { name: 'ERROR', bg: '#ff0000', text: '#000000', border: '#ffffff' },
];

export const FONTS = [
  { label: 'GROTESK', value: 'font-sans' },
  { label: 'MONO', value: 'font-mono' },
  { label: 'HEAVY', value: 'font-display' },
];

export const INITIAL_CONFIG = {
  text: 'DIGITE UM TEMA\nOU GERE COM IA',
  font: 'font-display' as const,
  fontSize: 60,
  alignment: 'text-left' as const,
  padding: 8,
  palette: PALETTES[2], // Acid green default
  hasNoise: true,
  uppercase: true,
};

import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedOption, Tone } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateStatusText = async (theme: string, tone: Tone): Promise<GeneratedOption[]> => {
  try {
    const prompt = `Crie 3 frases curtas e impactantes para Status de WhatsApp (Story) baseadas no tema: "${theme}" com o tom: "${tone}".

    Regras:
    - Máximo de 120 caracteres por frase.
    - Português do Brasil (pt-BR).
    - Estilo direto, sem hashtags, sem emojis excessivos.
    - Se o tom for "Sarcástico", seja ácido.
    - Se o tom for "Minimalista", use poucas palavras.
    - Se o tom for "Caótico", use pontuação não convencional ou Caps Lock.

    Retorne apenas um array JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            options: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    const json = JSON.parse(response.text || '{"options": []}');

    return json.options.map((text: string, index: number) => ({
      id: `gen-${Date.now()}-${index}`,
      text: text
    }));

  } catch (error) {
    console.error("Gemini API Error:", error);
    // Fallback stub in case of error (or dev mode without key)
    return [
      { id: 'err-1', text: 'ERRO NA MATRIX. TENTE DE NOVO.' },
      { id: 'err-2', text: 'A IA TIROU UMA FOLGA.' },
      { id: 'err-3', text: 'SEM SINAL. SEM STATUS.' }
    ];
  }
};

import React from 'react';
import { Tone, CardConfig, Palette, FontStyle, Alignment } from '../types';
import { TONES, PALETTES, FONTS } from '../constants';

interface ControlsProps {
  themeInput: string;
  setThemeInput: (v: string) => void;
  tone: Tone;
  setTone: (t: Tone) => void;
  isGenerating: boolean;
  onGenerate: () => void;
  config: CardConfig;
  setConfig: (c: CardConfig) => void;
  generatedOptions: { id: string, text: string }[];
  onSelectOption: (text: string) => void;
}

export const Controls: React.FC<ControlsProps> = ({
  themeInput, setThemeInput, tone, setTone, isGenerating, onGenerate,
  config, setConfig, generatedOptions, onSelectOption
}) => {

  const updateConfig = (key: keyof CardConfig, value: any) => {
    setConfig({ ...config, [key]: value });
  };

  return (
    <div className="flex flex-col gap-8 p-6 bg-white border-4 border-black shadow-hard-lg">

      {/* SECTION 1: AI INPUT */}
      <div className="space-y-4">
        <h2 className="font-display text-2xl bg-black text-white inline-block px-2 py-1">1. DADOS DE ENTRADA</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="flex flex-col gap-1">
            <label className="font-mono text-xs font-bold uppercase">Tema / Assunto</label>
            <input
              type="text"
              value={themeInput}
              onChange={(e) => setThemeInput(e.target.value)}
              placeholder="EX: ACADEMIA, CAFÉ, SAUDADE..."
