            />
          </div>
          <div className="flex flex-col gap-1">
            <label className="font-mono text-xs font-bold uppercase">Tom</label>
            <select
              value={tone}
              onChange={(e) => setTone(e.target.value as Tone)}
              className="border-4 border-black p-3 font-mono text-lg appearance-none bg-white focus:outline-none focus:bg-acid-green cursor-pointer"
            >
              {TONES.map(t => <option key={t} value={t}>{t.toUpperCase()}</option>)}
            </select>
          </div>
        </div>

        <button
          onClick={onGenerate}
          disabled={isGenerating || !themeInput.trim()}
          className={`w-full border-4 border-black p-4 font-display text-xl uppercase tracking-wider transition-all
            ${isGenerating ? 'bg-gray-300 cursor-wait' : 'bg-black text-white hover:bg-pure-red hover:shadow-hard active:translate-x-1 active:translate-y-1 active:shadow-none'}
          `}
        >
          {isGenerating ? 'PROCESSANDO...' : '/// GERAR TEXTO COM IA'}
        </button>

        {generatedOptions.length > 0 && (
          <div className="grid grid-cols-1 gap-2 mt-4 animate-fade-in">
            <label className="font-mono text-xs font-bold uppercase text-gray-500">SELECIONE UMA OPÇÃO:</label>
            {generatedOptions.map(opt => (
              <button
                key={opt.id}
                onClick={() => onSelectOption(opt.text)}
                className="text-left border-2 border-black p-2 font-mono text-sm hover:bg-acid-green transition-colors"
              >
                {">"} {opt.text}
              </button>
            ))}
          </div>
        )}
      </div>

      <hr className="border-2 border-black border-dashed" />

      {/* SECTION 2: EDITOR */}
      <div className="space-y-6">
        <h2 className="font-display text-2xl bg-black text-white inline-block px-2 py-1">2. ESTILO BRUTAL</h2>

        {/* Manual Text Edit */}
        <div className="flex flex-col gap-1">
          <label className="font-mono text-xs font-bold uppercase">Texto</label>
          <textarea
            value={config.text}
            onChange={(e) => updateConfig('text', e.target.value)}
            rows={3}
            className="border-4 border-black p-2 font-display text-lg w-full resize-none focus:outline-none focus:bg-acid-green"
          />
        </div>

        {/* Font & Alignment */}
        <div className="grid grid-cols-2 gap-4">
           <div>
            <label className="font-mono text-xs font-bold uppercase block mb-1">Fonte</label>
            <div className="flex flex-col gap-2">
              {FONTS.map(f => (
                <button
                  key={f.value}
                  onClick={() => updateConfig('font', f.value)}
                  className={`border-2 border-black p-1 text-xs font-bold uppercase ${config.font === f.value ? 'bg-black text-white' : 'hover:bg-gray-200'}`}
                >
                  {f.label}
                </button>
              ))}
            </div>
           </div>

           <div>
            <label className="font-mono text-xs font-bold uppercase block mb-1">Alinhamento</label>
            <div className="flex gap-1">
              {(['text-left', 'text-center', 'text-right'] as Alignment[]).map(align => (
                <button
                  key={align}
                  onClick={() => updateConfig('alignment', align)}
                  className={`flex-1 border-2 border-black p-2 ${config.alignment === align ? 'bg-black text-white' : 'hover:bg-gray-200'}`}
                >
                  {align === 'text-left' ? 'L' : align === 'text-center' ? 'C' : 'R'}
