              ))}
            </div>

            <label className="font-mono text-xs font-bold uppercase block mt-4 mb-1">Caps Lock</label>
             <button
              onClick={() => updateConfig('uppercase', !config.uppercase)}
              className={`w-full border-2 border-black p-1 text-xs font-bold ${config.uppercase ? 'bg-acid-green' : ''}`}
            >
