            />
          </div>
          <div>
            <label className="font-mono text-xs font-bold uppercase flex justify-between">
              <span>Margem</span>
              <span>{config.padding}</span>
            </label>
            <input
              type="range"
              min="0"
              max="24"
              value={config.padding}
              onChange={(e) => updateConfig('padding', parseInt(e.target.value))}
              className="w-full h-4 bg-gray-200 appearance-none border-2 border-black accent-black"
            />
          </div>
        </div>

        {/* Colors */}
        <div>
          <label className="font-mono text-xs font-bold uppercase block mb-2">Paleta</label>
          <div className="grid grid-cols-3 gap-2">
            {PALETTES.map(p => (
              <button
                key={p.name}
                onClick={() => updateConfig('palette', p)}
                className={`h-12 border-2 border-black relative overflow-hidden group ${config.palette.name === p.name ? 'ring-2 ring-offset-2 ring-black' : ''}`}
                style={{ backgroundColor: p.bg }}
              >
                <span className="absolute inset-0 flex items-center justify-center font-bold text-xs" style={{ color: p.text }}>
                  {p.name}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Noise Toggle */}
        <div className="flex items-center gap-2">
          <input
            type="checkbox"
            id="noise"
            checked={config.hasNoise}
            onChange={(e) => updateConfig('hasNoise', e.target.checked)}
