import React, { useState, useRef } from 'react';
import { INITIAL_CONFIG, getPaletteByName } from './constants';
import { CardConfig, GeneratedVariant } from './types';
import { Controls } from './components/Controls';
import { Preview } from './components/Preview';
import { generateStatusText } from './services/geminiService';

declare global {
  interface Window {
    html2canvas: any;
  }
}

export default function App() {
  // State: Input
  const [themeInput, setThemeInput] = useState('');
  // Tone state removed (AI decides now)

  // State: AI
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedVariants, setGeneratedVariants] = useState<GeneratedVariant[]>([]);
  const [selectedVariantId, setSelectedVariantId] = useState<string>('');

  // State: Editor (Driven by AI selection now)
  const [config, setConfig] = useState<CardConfig>(INITIAL_CONFIG);

  // State: Export
  const [isExporting, setIsExporting] = useState(false);
  const exportRef = useRef<HTMLDivElement>(null);

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedVariants([]);
    setSelectedVariantId('');

    // Call service without specific tone
    const results = await generateStatusText(themeInput);

    setGeneratedVariants(results);
    setIsGenerating(false);

    // Auto-select first variant
    if (results.length > 0) {
      handleSelectVariant(results[0]);
    }
  };

  const handleSelectVariant = (variant: GeneratedVariant) => {
    setSelectedVariantId(variant.id);

    // Map variant to config
    setConfig({
      text: variant.text,
      font: variant.font,
      fontSize: variant.fontSize,
      alignment: variant.alignment,
      padding: 12, // Default padding for all AI generated cards
      palette: getPaletteByName(variant.paletteName),
      hasNoise: variant.hasNoise,
      uppercase: variant.uppercase
    });
  };

  const handleExport = async () => {
    if (!exportRef.current || !window.html2canvas) {
      alert("Erro: Biblioteca de exportação não carregada.");
      return;
    }

    setIsExporting(true);

    try {
      const canvas = await window.html2canvas(exportRef.current, {
        scale: 1, // Already 1080x1920 logical pixels
        useCORS: true,
        backgroundColor: config.palette.bg, // Ensure no transparency
      });

      const image = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.href = image;
      link.download = `BRUTAL-STATUS-${Date.now()}.png`;
      link.click();
    } catch (err) {
      console.error("Export failed", err);
      alert("Falha ao exportar imagem.");
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="min-h-screen bg-off-white font-sans selection:bg-neon-pink selection:text-white pb-20">

      {/* Header */}
      <header className="border-b-4 border-black bg-acid-green p-4 md:p-6 sticky top-0 z-50 shadow-hard">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <h1 className="font-display text-2xl md:text-4xl uppercase tracking-tighter">
            BRUTAL <span className="text-stroke-white">STATUS</span> // GEN
          </h1>
          <div className="hidden md:block font-mono text-xs font-bold border-2 border-black px-2 py-1 bg-white">
            v1.2 AI-AUTO
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto p-4 md:p-8 grid grid-cols-1 lg:grid-cols-12 gap-8 mt-4">

        {/* Left Column: Controls (lg: 7 cols) */}
        <div className="lg:col-span-7 order-2 lg:order-1">
          <Controls 
            themeInput={themeInput}
            setThemeInput={setThemeInput}
            isGenerating={isGenerating}
            onGenerate={handleGenerate}
            generatedVariants={generatedVariants}
            onSelectVariant={handleSelectVariant}
            selectedVariantId={selectedVariantId}
          />
        </div>

        {/* Right Column: Preview (lg: 5 cols) */}
        <div className="lg:col-span-5 order-1 lg:order-2 flex flex-col items-center">
          <div className="sticky top-24 w-full flex justify-center">
            <Preview 
              config={config}
              exportRef={exportRef}
              onExport={handleExport}
              isExporting={isExporting}
            />
          </div>
        </div>

      </main>

      {/* Footer */}
      <footer className="mt-12 text-center font-mono text-xs opacity-50 p-4">
        POWERED BY GEMINI // BRUTALISM UI
      </footer>

    </div>
  );
}

import React from 'react';
import { CardConfig } from '../types';

interface PreviewProps {
  config: CardConfig;
  exportRef: React.RefObject<HTMLDivElement>;
  onExport: () => void;
  isExporting: boolean;
}

export const Preview: React.FC<PreviewProps> = ({ config, exportRef, onExport, isExporting }) => {

  // Helper to map font styles to Tailwind classes for maximum weight/impact
  const getFontClasses = (font: string) => {
    switch (font) {
      case 'font-sans': return 'font-black tracking-tighter'; // Inter 900
      case 'font-mono': return 'font-bold tracking-tighter';  // Space Mono 700
      case 'font-display': return 'font-normal tracking-tighter'; // Archivo Black (400 is heavy)
      default: return 'font-black';
    }
  };

  const fontClasses = getFontClasses(config.font);

  // Base styles for content
  const baseStyle = {
    backgroundColor: config.palette.bg,
    color: config.palette.text,
    fontFamily: config.font === 'font-sans' ? 'Inter, sans-serif' : config.font === 'font-mono' ? '"Space Mono", monospace' : '"Archivo Black", sans-serif',
  };

  // Uneven thick border style for the 1080p export
  // Scaled up for 1920x1080
  const exportBorderStyle = {
    borderColor: config.palette.border, // Use palette border color (usually black or white)
    borderStyle: 'solid',
    borderTopWidth: '40px',
    borderRightWidth: '60px',
    borderBottomWidth: '50px',
    borderLeftWidth: '50px',
    boxSizing: 'border-box' as const,
  };

  // Scaled down uneven border for the preview (~3.5x smaller)
  const previewBorderStyle = {
    borderColor: config.palette.border,
    borderStyle: 'solid',
    borderTopWidth: '11px',
    borderRightWidth: '17px',
    borderBottomWidth: '14px',
    borderLeftWidth: '14px',
    boxSizing: 'border-box' as const,
  };

  return (
    <div className="flex flex-col items-center gap-4 w-full">
       <div className="w-full flex justify-between items-end mb-2">
         <h2 className="font-display text-2xl bg-black text-white inline-block px-2 py-1">3. PREVIEW</h2>
         <span className="font-mono text-xs font-bold">9:16 AR</span>
       </div>

      {/* 
        VISUAL PREVIEW CONTAINER 
        This is what the user sees. It scales responsibly.
      */}
      <div className="relative w-full max-w-[320px] aspect-[9/16] shadow-hard-xl bg-gray-800 overflow-hidden">

        {/* Render content scaled to fit this container */}
        <div 
            className="w-full h-full flex flex-col relative"
            style={{ ...baseStyle, ...previewBorderStyle }}
        >
             {/* Noise Layer */}
            {config.hasNoise && <div className="absolute inset-0 bg-noise pointer-events-none mix-blend-overlay z-10 opacity-70"></div>}

            {/* Content Content */}
            <div 
              className={`flex-1 flex flex-col justify-center h-full w-full ${config.alignment}`}
              style={{ padding: `${config.padding * 4}px` }}
            >
              <p 
                className={`leading-[0.95] break-words whitespace-pre-wrap ${config.uppercase ? 'uppercase' : ''} ${fontClasses}`}
                style={{ 
                  fontSize: `${config.fontSize / 3.5}px` /* Scale down font for preview roughly */
                }}
              >
                {config.text || "SEU TEXTO AQUI"}
              </p>
            </div>
        </div>
      </div>

      <button
        onClick={onExport}
        disabled={isExporting}
        className="w-full max-w-[320px] border-4 border-black bg-acid-green p-4 font-display text-xl uppercase tracking-wider hover:bg-white hover:shadow-hard active:translate-x-1 active:translate-y-1 active:shadow-none transition-all disabled:opacity-50"
      >
        {isExporting ? 'GERANDO PNG...' : 'BAIXAR PNG (HD)'}
      </button>

      {/* 
        HIDDEN EXPORT CONTAINER 
        Fixed 1080x1920 resolution. Rendered off-screen or hidden.
        We use `fixed top-0 left-[-9999px]` to keep it out of view but renderable by html2canvas.
      */}
      <div 
        ref={exportRef}
        className="fixed top-0 left-[-9999px] w-[1080px] h-[1920px] flex flex-col overflow-hidden"
        style={{ ...baseStyle, ...exportBorderStyle }}
      >
          {config.hasNoise && <div className="absolute inset-0 bg-noise pointer-events-none mix-blend-overlay z-10 w-full h-full" style={{ backgroundSize: '400px' }}></div>}

          <div 
            className={`flex-1 flex flex-col justify-center h-full w-full relative z-0 ${config.alignment}`}
            style={{ padding: `${config.padding * 8}px` }} 
          >
            <p 
              className={`leading-[0.95] break-words whitespace-pre-wrap ${config.uppercase ? 'uppercase' : ''} ${fontClasses}`}
              style={{ 
                fontSize: `${config.fontSize * 1.8}px` /* True scale for 1080p */
              }}
            >
              {config.text || "SEU TEXTO AQUI"}
            </p>
          </div>
      </div>

    </div>
  );
};

