// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateStatusText = async (theme: string): Promise<GeneratedVariant[]> => {
  try {
    const prompt = `Analise o tema: "${theme}". Crie 3 opções completas de design para Status de WhatsApp com abordagens/tons DIFERENTES entre si.

    Para cada opção:
    1. Defina um TOM criativo que combine com o tema (ex: Sarcástico, Motivacional, Triste, Caótico, Minimalista, Agressivo).
    2. Gere uma frase curta e impactante (máx 120 caracteres, pt-BR) seguindo esse tom.
    3. Escolha as configurações visuais (fonte, paleta de cores, alinhamento) que potencializem esse tom.

    Paletas Disponíveis: "P&B", "DARK", "ACID", "BLUE", "WARNING", "ERROR".
    Fontes Disponíveis: "font-sans" (Grotesk), "font-mono" (Código), "font-display" (Pesada).

    Regras de Estilo:
    - Tons agressivos pedem cores de alerta e fontes pesadas.
    - Tons calmos/tristes pedem P&B ou Dark e fontes mono.
    - FontSize deve ser GRANDE, entre 60 e 110 (inteiro). O texto deve ocupar bem o espaço.

    Retorne apenas JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            variants: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  tone: { type: Type.STRING, description: "O tom escolhido (ex: Sarcástico)" },
                  text: { type: Type.STRING },
                  font: { type: Type.STRING, enum: ["font-sans", "font-mono", "font-display"] },
                  paletteName: { type: Type.STRING, enum: ["P&B", "DARK", "ACID", "BLUE", "WARNING", "ERROR"] },
                  alignment: { type: Type.STRING, enum: ["text-left", "text-center", "text-right"] },
                  fontSize: { type: Type.INTEGER },
                  hasNoise: { type: Type.BOOLEAN },
                  uppercase: { type: Type.BOOLEAN }
                }
              }
            }
          }
        }
      }
    });

    const json = JSON.parse(response.text || '{"variants": []}');

    return json.variants.map((item: any, index: number) => ({
      id: `gen-${Date.now()}-${index}`,
      tone: item.tone || 'AUTO',
      text: item.text,
      font: item.font,
      paletteName: item.paletteName,
      alignment: item.alignment,
      fontSize: item.fontSize,
      hasNoise: item.hasNoise,
      uppercase: item.uppercase
    }));

  } catch (error) {
    console.error("Gemini API Error:", error);
    // Fallback stub
    return [
      { 
        id: 'err-1', tone: 'ERRO', text: 'ERRO NA MATRIX.', font: 'font-mono', 
        paletteName: 'ERROR', alignment: 'text-left', fontSize: 60, hasNoise: true, uppercase: true 
      },
      { 
        id: 'err-2', tone: 'FALHA', text: 'TENTE NOVAMENTE.', font: 'font-display', 
        paletteName: 'DARK', alignment: 'text-center', fontSize: 50, hasNoise: false, uppercase: true 
      }
    ];
  }
};

