import React from 'react';
import { GeneratedVariant } from '../types';

interface ControlsProps {
  themeInput: string;
  setThemeInput: (v: string) => void;
  isGenerating: boolean;
  onGenerate: () => void;
  generatedVariants: GeneratedVariant[];
  onSelectVariant: (variant: GeneratedVariant) => void;
  selectedVariantId?: string;
}

export const Controls: React.FC<ControlsProps> = ({
  themeInput, setThemeInput, isGenerating, onGenerate,
  generatedVariants, onSelectVariant, selectedVariantId
}) => {

  const getFontClasses = (font: string) => {
    switch (font) {
      case 'font-sans': return 'font-black tracking-tighter';
      case 'font-mono': return 'font-bold tracking-tighter';
      default: return 'font-display tracking-tighter';
    }
  };

  const buttonText = isGenerating ? 'PROCESSANDO...' : '/// GERAR DESIGN';

  return (
    <div className="flex flex-col gap-8 p-6 bg-white border-4 border-black shadow-hard-lg">

      {/* INPUT SECTION */}
      <div className="space-y-4">
        <h2 className="font-display text-2xl bg-black text-white inline-block px-2 py-1">1. CONCEITO</h2>
        <p className="font-mono text-xs text-gray-500">
          A I.A. ESCOLHERÁ O TOM, O TEXTO E O DESIGN.
        </p>

        <div className="flex flex-col gap-1">
          <label className="font-mono text-xs font-bold uppercase">Tema / Assunto</label>
          <input
            type="text"
            value={themeInput}
            onChange={(e) => setThemeInput(e.target.value)}
            placeholder="EX: TREINO, SAUDADE, PIZZA..."
            className="border-4 border-black p-3 font-mono text-lg focus:outline-none focus:bg-acid-green placeholder-gray-400"
          />
        </div>

        <button
          onClick={onGenerate}
          disabled={isGenerating || !themeInput.trim()}
          data-text={buttonText}
          className={`glitch-btn w-full border-4 border-black p-4 font-display text-xl uppercase tracking-wider transition-all
            ${isGenerating ? 'bg-gray-300 cursor-wait' : 'bg-black text-white hover:shadow-hard active:translate-x-1 active:translate-y-1 active:shadow-none'}
          `}
        >
          {buttonText}
        </button>
      </div>

      <hr className="border-2 border-black border-dashed" />

      {/* VARIANTS SELECTION */}
      <div className="space-y-4">
        <h2 className="font-display text-2xl bg-black text-white inline-block px-2 py-1">2. ESCOLHA</h2>

        {generatedVariants.length === 0 ? (
          <div className="p-8 border-2 border-dashed border-gray-300 text-center font-mono text-sm text-gray-400">
            AGUARDANDO GERAÇÃO...
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-3 animate-fade-in">
            {generatedVariants.map(variant => (
              <button
                key={variant.id}
                onClick={() => onSelectVariant(variant)}
                className={`group text-left border-4 p-4 transition-all duration-150 ease-out relative overflow-hidden ${
                  selectedVariantId === variant.id 
                    ? 'border-black bg-acid-green shadow-hard -translate-y-1 -translate-x-1 scale-105 z-10' 
